(() => {
  const pathName = window.location.pathname;
  const state = { user: null, classes: [], grades: {}, currentClass: null, students: [], attendance: null, editing: null, postLoginView: null, adminDate: null };
  const $ = (id) => document.getElementById(id);
  const esc = (value) => String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
  const fmtDate = (value) => value ? new Intl.DateTimeFormat(undefined, { dateStyle:'medium' }).format(new Date(`${value.slice(0,10)}T00:00:00`)) : '—';
  const fmtDateTime = (value) => value ? new Intl.DateTimeFormat(undefined, { dateStyle:'medium', timeStyle:'short' }).format(new Date(value)) : '—';
  const initials = (name) => String(name || 'DS').split(/\s+/).map(part => part[0]).join('').slice(0,2).toUpperCase();
  const sortStudentsById = (students) => [...students].sort((a,b) => String(a.student_id).localeCompare(String(b.student_id), undefined, { numeric:true, sensitivity:'base' }));
  let toastTimer;
  function showToast(message, error = false) { const el = $('toast'); if (!el) return; el.textContent = message; el.className = `toast show${error ? ' error' : ''}`; clearTimeout(toastTimer); toastTimer = setTimeout(() => { el.className = 'toast'; }, 3400); }
  async function api(url, options = {}) { const response = await fetch(url, { headers: { 'Content-Type':'application/json', ...(options.headers || {}) }, ...options }); const data = await response.json().catch(() => ({})); if (!response.ok) { const error = new Error(data.error || 'The request could not be completed.'); error.status = response.status; throw error; } return data; }
  function openModal(id) { $(id)?.classList.remove('hidden'); }
  function closeModal(id) { $(id)?.classList.add('hidden'); }
  document.addEventListener('click', (event) => { const close = event.target.closest('[data-close]'); if (close) closeModal(close.dataset.close); if (event.target.classList.contains('modal-backdrop')) event.target.classList.add('hidden'); });
  function setPage(title, kicker = 'SCHOOL OPERATIONS') { if ($('pageTitle')) $('pageTitle').textContent = title; if ($('pageKicker')) $('pageKicker').textContent = kicker; }
  function setupGradeSelects() {
    if (!$('loginGrade')) return;
    $('loginGrade').innerHTML = Object.keys(state.grades).map(g => `<option value="${g}">Grade ${g}</option>`).join('');
    updateSections(); $('loginGrade').addEventListener('change', updateSections);
    ['parentVerifyClass','parentReasonClass'].forEach(id => { if ($(id)) $(id).innerHTML = state.classes.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join(''); });
    $('transferClass').innerHTML = state.classes.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join('');
  }
  function updateSections() { const grade = $('loginGrade')?.value; if ($('loginSection')) $('loginSection').innerHTML = (state.grades[grade] || []).map(s => `<option value="${s}">${s}</option>`).join(''); }
  function initLanding() {
    $('classLoginButton')?.addEventListener('click', () => {
      state.postLoginView = null;
      $('loginMode').value='class'; $('loginHeading').textContent='Login to your class';
      $('loginDescription').textContent='Use the staff credentials issued by your school administrator.';
      $('classFields').classList.remove('hidden'); $('loginGrade').required=true; $('loginSection').required=true;
      $('loginSubmit').textContent='CONTINUE  →'; $('loginError').textContent=''; openModal('loginModal');
    });
    $('adminLoginButton')?.addEventListener('click', () => {
      state.postLoginView = 'admin';
      $('loginMode').value='admin'; $('loginHeading').textContent='School administration login';
      $('loginDescription').textContent='Principal and authorized school leaders can view school-wide student and staff registration.';
      $('classFields').classList.add('hidden'); $('loginGrade').required=false; $('loginSection').required=false;
      $('loginSubmit').textContent='OPEN DASHBOARD  →'; $('loginError').textContent=''; openModal('loginModal');
    });
    $('staffRegistrationButton')?.addEventListener('click', openStaffRegistrationModal);
    $('loginForm')?.addEventListener('submit', handleLogin);
    $('staffForm')?.addEventListener('submit', saveStaffRegistration);
    document.querySelectorAll('[data-parent-tool]').forEach(button => button.addEventListener('click', () => openParentTool(button.dataset.parentTool)));
    $('parentVerifyForm')?.addEventListener('submit', verifyParentStudent);
    $('parentReasonForm')?.addEventListener('submit', submitParentAbsenceReason);
    loadLandingOverview();
  }

  async function loadLandingOverview() {
    try {
      const data = await api('/api/overview');
      $('landingRegistered').textContent = `${data.registeredClasses} / ${data.totalClasses}`;
      $('landingAttendance').textContent = `${data.attendancePercent}%`;
      if ($('landingAttendanceSub')) $('landingAttendanceSub').textContent = data.registeredStudents ? `${data.present} present of ${data.registeredStudents} registered students` : 'No student registrations yet';
      if ($('landingProgress')) $('landingProgress').style.width = `${data.totalClasses ? Math.round(data.registeredClasses / data.totalClasses * 100) : 0}%`;
      if ($('landingProgressLabel')) $('landingProgressLabel').textContent = `${data.registeredClasses} of ${data.totalClasses} classes`;
    } catch (_) {}
  }

  async function handleLogin(event) { event.preventDefault(); $('loginError').textContent=''; const body={ staffId:$('staffId').value.trim(), password:$('staffPassword').value, mode:$('loginMode').value, grade:$('loginGrade').value, section:$('loginSection').value }; try { const data=await api('/api/login',{method:'POST',body:JSON.stringify(body)}); state.user=data.user; closeModal('loginModal'); $('landing').classList.add('hidden'); await loadApp(); if (state.postLoginView) { const target=state.postLoginView; state.postLoginView=null; if (target==='staff' && ['Principal','Vice Principal','Assistant Principal','administrator'].includes(state.user.role)) await navigate('staff'); } } catch (error) { $('loginError').textContent=error.message; }
  }
  async function bootstrap() {
    try { const data=await api('/api/session'); state.classes=data.classes; state.grades=data.grades; setupGradeSelects(); if (data.user && !pathName.startsWith('/DB/')) { state.user=data.user; $('landing')?.classList.add('hidden'); await loadApp(); } else if (!pathName.startsWith('/DB/')) initLanding(); } catch (error) { if (!pathName.startsWith('/DB/')) { initLanding(); showToast('Unable to connect to the server.', true); } }
  }
  async function loadApp() { $('appShell').classList.remove('hidden'); $('landing')?.classList.add('hidden'); $('sidebarAvatar').textContent=initials(state.user.name); $('topAvatar').textContent=initials(state.user.name); $('sidebarUserName').textContent=state.user.name; $('sidebarUserRole').textContent=state.user.role; $('currentDate').textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date()); buildNav(); bindGlobalAppEvents(); await navigate(state.user.role === 'Class Teacher' || state.user.role === 'Assistant Class Teacher' ? 'dashboard' : 'admin'); }
  function buildNav() { const isTeacher=state.user.role.includes('Teacher'); const items=isTeacher ? [['dashboard','⌂','Dashboard'],['attendance','▣',"Today's Registration"],['students','☷','Student List'],['view','◌','View Attendance'],['transfer','⇄','Remove / Transfer']] : [['admin','⌂','School Dashboard'],['staff','♙','Staff Registration'],['view','◌','View Class Attendance'],['audit','≡','Audit Log']]; $('mainNav').innerHTML=items.map(([id,icon,label])=>`<button class="nav-button" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join(''); document.querySelectorAll('.admin-only').forEach(el => el.style.display=isTeacher?'none':'flex'); }
  function bindGlobalAppEvents() { document.querySelectorAll('.nav-button').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.view))); $('logoutButton')?.addEventListener('click', async()=>{ await api('/api/logout',{method:'POST'}); window.location.href='/'; }); $('studentForm')?.addEventListener('submit',saveStudent); $('transferForm')?.addEventListener('submit',transferStudent); $('staffForm')?.removeEventListener('submit',saveStaffRegistration); $('staffForm')?.addEventListener('submit',saveStaffRegistration); $('confirmAttendanceButton')?.addEventListener('click',submitAttendance); }
  function activeNav(id) { document.querySelectorAll('.nav-button').forEach(button=>button.classList.toggle('active',button.dataset.view===id)); }
  async function navigate(view) { activeNav(view); state.view=view; try { if(view==='admin') return renderAdminDashboard(); if(view==='staff') return renderStaffRegistration(); if(view==='dashboard') return renderTeacherDashboard(); if(view==='attendance') return renderAttendance(state.user.assignedClass); if(view==='students') return renderStudents(state.user.assignedClass); if(view==='view') return renderClassViewer(); if(view==='transfer') return renderTransferView(); if(view==='audit') return renderAudit(); } catch(error) { showToast(error.message,true); }
  }
  function renderStats(stats, admin=false) { const cards=admin ? [['Total Students',stats.total,'School-wide active records'],['Present Today',stats.present,'Across registered classes'],['Absent Today',stats.absent,'Across registered classes'],['Attendance %',`${stats.attendancePercent}%`,'Based on active students'],['Male Students',stats.male,'Active records'],['Female Students',stats.female,'Active records'],['Male Present',stats.malePresent,'Today'],['Female Present',stats.femalePresent,'Today']] : [['Total Students',stats.total,'Active students'],['Present Today',stats.present,'Today'],['Absent Today',stats.absent,'Today'],['Attendance %',`${stats.total ? Math.round(stats.present/stats.total*1000)/10 : 0}%`,'Class attendance']]; return `<div class="stats-grid">${cards.map(([label,value,sub],i)=>`<div class="stat-card ${i===1||i===3?'yellow-card':''}"><small>${label}</small><strong>${value}</strong><div class="substat">${sub}</div></div>`).join('')}</div>`; }
  async function renderTeacherDashboard() { setPage('Class dashboard'); state.currentClass=state.user.assignedClass; const data=await api(`/api/attendance/today?class=${encodeURIComponent(state.currentClass)}`); data.students=sortStudentsById(data.students); state.students=data.students; state.attendance=data.registration; const stats={total:data.students.length,present:data.registration?.present||0,absent:data.registration?.absent||0}; $('viewContainer').innerHTML=`<div class="view"><div class="welcome-row"><div><p class="eyebrow">${esc(state.currentClass)} · ${fmtDate(data.date)}</p><h3>Good day, ${esc(state.user.name.split(' ')[0])}</h3><p class="muted">Keep your class record complete and up to date.</p></div><button class="button button-primary" id="newStudentButton">+ NEW STUDENT</button></div>${renderStats(stats)}<div class="section-card"><div class="section-card-header"><div><h3>Today's registration</h3><p class="muted">${data.registration ? 'Submitted and locked for today.' : 'Mark each student before submitting the daily record.'}</p></div><button class="button button-secondary button-small" data-view-action="attendance">OPEN REGISTRATION →</button></div>${data.registration ? renderRegistrationSummary(data.registration) : renderPendingCallout(data.students.length)}</div><div class="section-card"><div class="section-card-header"><div><h3>Student list</h3><p class="muted">Double-click a name to open the full profile.</p></div><button class="button button-secondary button-small" data-view-action="students">VIEW ALL STUDENTS →</button></div>${renderStudentTable(data.students.slice(0,6),true)}</div></div>`; $('newStudentButton').addEventListener('click',()=>openStudentModal()); document.querySelectorAll('[data-view-action]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.viewAction))); bindProfileButtons(); }
  function renderPendingCallout(total) { return `<div class="readonly-banner" style="background:#eff8f1;color:#176746"><strong>${total}</strong> active students are waiting for today's registration. All students default to Present.</div>`; }
  function renderRegistrationSummary(reg) { return `<div class="attendance-summary">${[['Total',reg.total_students],['Present',reg.present],['Absent',reg.absent],['Male present',reg.male_present],['Female present',reg.female_present],['Male absent',reg.male_absent],['Female absent',reg.female_absent]].map(([l,v])=>`<div class="summary-pill"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><span class="status-badge present">SUBMITTED ${fmtDateTime(reg.submitted_at)}</span>`; }
  function renderStudentTable(students, compact=false) { if(!students.length) return '<div class="empty-state">No active students are recorded for this class.</div>'; return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Register no.</th><th>Student ID</th><th>Identification no.</th><th>Name</th><th>House</th><th>Gender</th><th>DOB</th><th>Age</th><th>Status</th>${compact?'':'<th>Action</th>'}</tr></thead><tbody>${students.map(s=>`<tr><td>${esc(s.register_number ?? '—')}</td><td>${esc(s.student_id)}</td><td>${esc(s.identification_number)}</td><td><button class="name-button profile-button" data-student="${esc(s.student_id)}" title="Double-click to view profile">${esc(s.full_name)}</button></td><td>${esc(s.gender)}</td><td>${fmtDate(s.date_of_birth)}</td><td>${s.age ?? '—'}</td><td><span class="status-badge active">ACTIVE</span></td>${compact?'':`<td><button class="button button-secondary button-small profile-button" data-student="${esc(s.student_id)}">VIEW</button></td>`}</tr>`).join('')}</tbody></table></div>`; }
  async function renderStudents(className) { setPage('Student list'); state.currentClass=className; const data=await api(`/api/students?class=${encodeURIComponent(className)}`); data.students=sortStudentsById(data.students); state.students=data.students; $('viewContainer').innerHTML=`<div class="view"><div class="welcome-row"><div><p class="eyebrow">${esc(className)}</p><h3>Student information</h3><p class="muted">Search, review, and manage active students in this class.</p></div><button class="button button-primary" id="newStudentButton">+ NEW STUDENT</button></div><div class="section-card"><div class="section-card-header"><h3>${data.students.length} active students</h3><div class="toolbar"><input class="search-input" id="studentSearch" placeholder="Search ID or name"><span class="sort-label">Sorted by student ID</span></div></div><div id="studentTableArea">${renderStudentTable(data.students)}</div></div></div>`; $('newStudentButton').addEventListener('click',()=>openStudentModal()); $('studentSearch').addEventListener('input',filterStudents); bindProfileButtons(); }
  function filterStudents() { const q=($('studentSearch').value||'').toLowerCase(); const rows=state.students.filter(s=>`${s.student_id} ${s.full_name} ${s.gender}`.toLowerCase().includes(q)).sort((a,b)=>String(a.student_id).localeCompare(String(b.student_id),undefined,{numeric:true,sensitivity:'base'})); $('studentTableArea').innerHTML=renderStudentTable(rows); bindProfileButtons(); }
  function bindProfileButtons() { document.querySelectorAll('.profile-button').forEach(button=>{ button.addEventListener('click',()=>openProfile(button.dataset.student)); button.addEventListener('dblclick',()=>openProfile(button.dataset.student)); }); }
  async function openProfile(studentId) { try { const data=await api(`/api/students/${encodeURIComponent(studentId)}`); state.editing=data.student; $('profileName').textContent=data.student.full_name; const s=data.student; $('profileContent').innerHTML=[['Student ID',s.student_id],['Class',s.class_name],['Age',s.age ?? '—'],['Date of birth',fmtDate(s.date_of_birth)],['Gender',s.gender],['Status',s.status],['Parent / Guardian',s.guardian_name],['Phone',s.guardian_phone],['Emergency contact',s.emergency_contact],['Address',s.address],['Notes',s.notes || '—']].map(([l,v],i)=>`<div class="profile-item ${i>8?'full':''}"><small>${l}</small><strong>${esc(v)}</strong></div>`).join(''); $('profileActions').innerHTML=`<button class="button button-secondary" data-close="profileModal">CLOSE</button>${state.user.role.includes('Teacher')||['Principal','Vice Principal','Assistant Principal'].includes(state.user.role)?`<button class="button button-secondary" id="editProfileButton">EDIT STUDENT</button><button class="button button-danger" id="transferProfileButton">REMOVE / TRANSFER</button>`:''}`; $('editProfileButton')?.addEventListener('click',()=>{closeModal('profileModal');openStudentModal(s);}); $('transferProfileButton')?.addEventListener('click',()=>{closeModal('profileModal');openTransferModal(s);}); openModal('profileModal'); } catch(error) { showToast(error.message,true); } }
  function openStudentModal(student=null) { state.editing=student; $('studentModalTitle').textContent=student?'Edit student':'Add new student'; $('studentModalKicker').textContent=student?'EDIT RECORD':'NEW STUDENT'; $('editingStudentId').value=student?.student_id||''; $('studentId').value=student?.student_id||''; $('studentId').disabled=Boolean(student); $('studentRegisterNumber').value=student?.register_number||''; $('studentIdentification').value=student?.identification_number||''; $('studentHouse').value=student?.house||''; $('studentName').value=student?.full_name||''; $('studentDob').value=student?.date_of_birth||''; $('studentGender').value=student?.gender||''; $('studentGuardian').value=student?.guardian_name||''; $('studentPhone').value=student?.guardian_phone||''; $('studentAddress').value=student?.address||''; $('studentEmergency').value=student?.emergency_contact||''; $('studentNotes').value=student?.notes||''; $('studentFormError').textContent=''; openModal('studentModal'); }
  async function saveStudent(event) { event.preventDefault(); $('studentFormError').textContent=''; const body={student_id:$('studentId').value,register_number:$('studentRegisterNumber').value,identification_number:$('studentIdentification').value,house:$('studentHouse').value,full_name:$('studentName').value.trim(),date_of_birth:$('studentDob').value,gender:$('studentGender').value,guardian_name:$('studentGuardian').value.trim(),guardian_phone:$('studentPhone').value.trim(),address:$('studentAddress').value.trim(),emergency_contact:$('studentEmergency').value.trim(),notes:$('studentNotes').value.trim(),class_name:state.currentClass||state.user.assignedClass}; try { if(state.editing) await api(`/api/students/${encodeURIComponent(state.editing.student_id)}`,{method:'PUT',body:JSON.stringify(body)}); else await api('/api/students',{method:'POST',body:JSON.stringify(body)}); closeModal('studentModal'); showToast(state.editing?'Student record updated.':'Student added successfully.'); await navigate(state.view==='students'?'students':'dashboard'); } catch(error) { $('studentFormError').textContent=error.message; } }
  async function renderAttendance(className) { setPage("Today's registration"); state.currentClass=className; const data=await api(`/api/attendance/today?class=${encodeURIComponent(className)}`); data.students=sortStudentsById(data.students); state.students=data.students; state.attendance=data.registration; const readOnly=data.readOnly || Boolean(data.registration); $('viewContainer').innerHTML=`<div class="view"><div class="welcome-row"><div><p class="eyebrow">${esc(className)} · ${fmtDate(data.date)}</p><h3>Daily registration</h3><p class="muted">${readOnly?'This record is locked or read only.':'Mark each student Present or Absent, then submit once.'}</p></div><div class="toolbar no-print"><button class="button button-secondary" id="printClassAttendanceButton">PRINT CLASS REGISTER</button>${readOnly?'':'<button class="button button-primary" id="submitAttendanceButton">SUBMIT DAILY REGISTRATION</button>'}</div></div>${readOnly&&data.readOnly?'<div class="readonly-banner no-print">READ ONLY · You are viewing another class. No changes can be made here.</div>':''}<div class="section-card"><div class="attendance-print-header"><strong>Gamini Central College Nuwara Eliya</strong><span>${esc(className)} · Daily Registration · ${esc(fmtDate(data.date))}</span></div><div class="attendance-summary no-print" id="liveAttendanceSummary"></div><div class="data-table-wrap"><table class="data-table attendance-table"><thead><tr><th>Class ID</th><th>Student name</th><th>Present</th><th>Absent</th></tr></thead><tbody>${data.students.map(s=>{const existing=data.registration?.absent_students?.some(a=>a.studentId===s.student_id); const status=existing?'absent':'present'; return `<tr data-student-row="${esc(s.student_id)}" class="${status==='absent'?'row-absent':''}"><td data-label="Class ID">${esc(s.student_id)}</td><td data-label="Student name">${esc(s.full_name)}</td><td data-label="Present" class="attendance-mark"><label class="radio-label"><input type="radio" name="att-${esc(s.student_id)}" value="present" ${status==='present'?'checked':''} ${readOnly?'disabled':''}><span>Present</span></label></td><td data-label="Absent" class="attendance-mark"><label class="radio-label"><input type="radio" name="att-${esc(s.student_id)}" value="absent" ${status==='absent'?'checked':''} ${readOnly?'disabled':''}><span>Absent</span></label></td></tr>`}).join('')}</tbody></table></div></div></div>`; $('printClassAttendanceButton').addEventListener('click',()=>window.print()); if(!readOnly) { document.querySelectorAll('.attendance-table input').forEach(input=>input.addEventListener('change',updateAttendanceSummary)); $('submitAttendanceButton').addEventListener('click',openAttendanceConfirmation); } updateAttendanceSummary(); }
  function getAttendanceValues() { return state.students.map(s=>({studentId:s.student_id,status:document.querySelector(`input[name="att-${CSS.escape(s.student_id)}"]:checked`)?.value||'present'})); }
  function computeSummary(values=getAttendanceValues()) { const byId=new Map(state.students.map(s=>[s.student_id,s])); const present=values.filter(v=>v.status==='present').map(v=>byId.get(v.studentId)); const absent=values.filter(v=>v.status==='absent').map(v=>byId.get(v.studentId)); return {total:state.students.length,present:present.length,absent:absent.length,malePresent:present.filter(s=>s.gender==='Male').length,femalePresent:present.filter(s=>s.gender==='Female').length,maleAbsent:absent.filter(s=>s.gender==='Male').length,femaleAbsent:absent.filter(s=>s.gender==='Female').length}; }
  function updateAttendanceSummary() { const summary=state.attendance ? {total:state.attendance.total_students,present:state.attendance.present,absent:state.attendance.absent,malePresent:state.attendance.male_present,femalePresent:state.attendance.female_present,maleAbsent:state.attendance.male_absent,femaleAbsent:state.attendance.female_absent} : computeSummary(); if($('liveAttendanceSummary')) $('liveAttendanceSummary').innerHTML=[['Total',summary.total],['Present',summary.present],['Absent',summary.absent],['Male present',summary.malePresent],['Female present',summary.femalePresent],['Male absent',summary.maleAbsent],['Female absent',summary.femaleAbsent]].map(([l,v])=>`<div class="summary-pill"><small>${l}</small><strong>${v}</strong></div>`).join(''); document.querySelectorAll('[data-student-row]').forEach(row=>{const id=row.dataset.studentRow; const status=document.querySelector(`input[name="att-${CSS.escape(id)}"]:checked`)?.value; row.classList.toggle('row-absent',status==='absent');}); }
  function openAttendanceConfirmation() { const s=computeSummary(); $('attendanceConfirmText').textContent=`You are about to submit today's attendance for ${state.currentClass}.`; $('attendanceConfirmStats').innerHTML=[['Total',s.total],['Present',s.present],['Absent',s.absent],['Male present',s.malePresent],['Female present',s.femalePresent],['Male absent',s.maleAbsent],['Female absent',s.femaleAbsent]].map(([l,v])=>`<div class="confirm-stat"><small>${l}</small><strong>${v}</strong></div>`).join(''); $('attendanceConfirmError').textContent=''; openModal('attendanceConfirmModal'); }
  async function submitAttendance() { const s=computeSummary(); $('attendanceConfirmError').textContent=''; if(s.total!==s.present+s.absent || s.present!==s.malePresent+s.femalePresent || s.absent!==s.maleAbsent+s.femaleAbsent) { $('attendanceConfirmError').textContent='The attendance totals do not balance. Please review the entries.'; return; } try { await api('/api/attendance',{method:'POST',body:JSON.stringify({class_name:state.currentClass,statuses:getAttendanceValues()})}); closeModal('attendanceConfirmModal'); showToast('Daily registration submitted and locked.'); await renderAttendance(state.currentClass); } catch(error) { $('attendanceConfirmError').textContent=error.message; } }
  async function renderClassViewer() { setPage('View class attendance'); const selected=state.currentClass||state.user.assignedClass||state.classes[0]; $('viewContainer').innerHTML=`<div class="view"><div class="welcome-row"><div><p class="eyebrow">READ-ONLY RECORDS</p><h3>View class attendance</h3><p class="muted">Authorized staff can review any class. Teachers cannot modify another class's records.</p></div></div><div class="section-card"><div class="toolbar"><select id="classViewerSelect">${state.classes.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="button button-secondary" id="loadClassButton">VIEW CLASS</button></div></div><div id="classViewerResult"></div></div>`; $('loadClassButton').addEventListener('click',()=>loadClassViewer($('classViewerSelect').value)); await loadClassViewer(selected); }
  async function loadClassViewer(className) { state.currentClass=className; const data=await api(`/api/attendance/today?class=${encodeURIComponent(className)}`); const history=await api(`/api/attendance/history?class=${encodeURIComponent(className)}`); $('classViewerResult').innerHTML=`<div class="section-card"><div class="section-card-header"><div><h3>${esc(className)}</h3><p class="muted">${fmtDate(data.date)}</p></div><span class="status-badge read-only">READ ONLY</span></div>${data.registration?renderRegistrationSummary(data.registration):'<div class="empty-state">This class has not submitted today\'s registration.</div>'}<h3 style="margin:26px 0 13px">Recent history</h3>${history.registrations.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Total</th><th>Present</th><th>Absent</th><th>Submitted by</th><th>Time</th></tr></thead><tbody>${history.registrations.map(r=>`<tr><td>${fmtDate(r.registration_date)}</td><td>${r.total_students}</td><td>${r.present}</td><td>${r.absent}</td><td>${esc(r.teacher_id)}</td><td>${fmtDateTime(r.submitted_at)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No registration history is available.</div>'}</div>`; }
  function openTransferModal(student) { $('transferStudentId').value=student.student_id; $('transferStudentName').textContent=`Selected student: ${student.full_name} (${student.student_id})`; $('transferClass').value=state.classes.find(c=>c!==student.class_name)||state.classes[0]; $('transferClassLabel').classList.remove('hidden'); $('transferAction').value='transfer'; $('transferReason').value=''; $('transferError').textContent=''; $('transferAction').onchange=()=> $('transferClassLabel').classList.toggle('hidden',$('transferAction').value!=='transfer'); openModal('transferModal'); }
  async function transferStudent(event) { event.preventDefault(); $('transferError').textContent=''; try { await api(`/api/students/${encodeURIComponent($('transferStudentId').value)}/transfer`,{method:'POST',body:JSON.stringify({action:$('transferAction').value,newClass:$('transferClass').value,reason:$('transferReason').value})}); closeModal('transferModal'); showToast('Student record action completed.'); await navigate('students'); } catch(error) { $('transferError').textContent=error.message; } }
  async function renderTransferView() { setPage('Remove / transfer student'); state.currentClass=state.user.assignedClass; const data=await api(`/api/students?class=${encodeURIComponent(state.currentClass)}`); state.students=data.students; $('viewContainer').innerHTML=`<div class="view"><div class="welcome-row"><div><p class="eyebrow">${esc(state.currentClass)}</p><h3>Remove / transfer student</h3><p class="muted">Records are retained with an audit trail instead of disappearing.</p></div></div><div class="section-card"><h3>Active students</h3><p class="muted" style="margin:6px 0 17px">Choose a student to transfer, mark inactive, or record that they left school.</p>${renderStudentTable(data.students)}</div></div>`; bindProfileButtons(); document.querySelectorAll('.profile-button').forEach(button=>button.addEventListener('contextmenu',event=>{event.preventDefault(); const s=state.students.find(student=>student.student_id===button.dataset.student); if(s) openTransferModal(s);})); }
  async function renderAdminDashboard(date = state.adminDate || new Date().toISOString().slice(0,10)) {
    setPage('School-wide student registration','SCHOOL-WIDE OVERVIEW');
    state.adminDate = date;
    const data = await api(`/api/admin/dashboard?date=${encodeURIComponent(date)}`);
    const pct = data.totalClasses ? Math.round(data.registeredClasses/data.totalClasses*100) : 0;
    const grouped = {};
    data.sections.forEach(item => { (grouped[item.grade] ||= []).push(item); });
    $('viewContainer').innerHTML = `<div class="view">
      <div class="welcome-row">
        <div><p class="eyebrow">${esc(state.user.role)} · ${fmtDate(data.date)}</p>
        <h3>School-wide student registration</h3>
        <p class="muted">A complete school-wide record of student registration, organized by grade and section.</p></div>
        <div class="toolbar"><label class="date-filter-label">Registration date<input id="adminDate" type="date" value="${esc(data.date)}"></label><button class="button button-secondary" id="loadAdminDate">VIEW DATE</button><button class="button button-secondary" id="printStudentRegistration">PRINT STUDENT REGISTRATION</button></div>
      </div>
      ${renderStats(data.stats,true)}
      <div class="section-card principal-tools-card"><div class="section-card-header"><div><h3>Parent services & school noticeboard</h3><p class="muted">Publish a notice that appears in the public top menu. Parents’ absence reasons will appear below.</p></div></div>
        <form id="principalMessageForm"><label>Message for students, parents and staff<textarea id="principalMessageInput" rows="3" maxlength="1000" placeholder="Example: Staff and student meeting will be held…"></textarea></label><div class="modal-actions"><button class="button button-primary" type="submit">PUBLISH MESSAGE</button></div><div id="principalMessageError" class="form-error"></div></form>
        <div class="section-card-header" style="margin-top:24px"><div><h3>Absence reasons received today</h3><p class="muted">Parent submissions linked to students marked absent.</p></div><button class="button button-secondary button-small" id="refreshAbsenceReasons">REFRESH</button></div><div id="absenceReasonList" class="absence-reason-list">Loading…</div>
      </div>
      <div class="admin-overview">
        <div class="section-card"><div class="section-card-header"><div><h3>Registration completion</h3><p class="muted">Classes registered for ${fmtDate(data.date)}</p></div><strong class="large-stat">${data.registeredClasses} / ${data.totalClasses}</strong></div>
          <div class="progress-summary"><div class="progress-track"><i style="width:${pct}%"></i></div><span class="section-label">${pct}%</span></div>
          <p class="muted" style="margin-top:14px">${data.totalClasses-data.registeredClasses} classes pending registration.</p>
        </div>
        <div class="section-card"><h3>School-wide attendance</h3><p class="muted">${data.stats.present + data.stats.absent} students represented in submitted class records.</p>
          <div class="attendance-summary" style="margin-top:20px;grid-template-columns:1fr 1fr 1fr"><div class="summary-pill"><small>Present</small><strong>${data.stats.present}</strong></div><div class="summary-pill"><small>Absent</small><strong>${data.stats.absent}</strong></div><div class="summary-pill"><small>Attendance</small><strong>${data.stats.attendancePercent}%</strong></div></div>
        </div>
      </div>
      <div class="section-card">
        <div class="section-card-header"><div><h3>Student registration by class and section</h3><p class="muted">School-wide record · each class is shown by section in a structured table.</p></div><span class="status-badge ${data.isToday?'present':'read-only'}">${data.isToday?'TODAY':'RECORD DATE'}</span></div>
        ${Object.entries(grouped).map(([grade,items]) => `<div class="class-section"><h4>Grade ${esc(grade)}</h4><div class="data-table-wrap"><table class="data-table school-registration-table"><thead><tr><th>Class</th><th>Section</th><th>Active students</th><th>Registration</th><th>Present</th><th>Absent</th><th>Attendance %</th></tr></thead><tbody>${items.map(item => `<tr><td><strong>${esc(item.className)}</strong></td><td>${esc(item.section)}</td><td>${item.studentCount}</td><td>${item.registration ? '<span class="status-badge present">REGISTERED</span>' : '<span class="status-badge pending">PENDING</span>'}</td><td>${item.registration ? item.registration.present : '—'}</td><td>${item.registration ? item.registration.absent : '—'}</td><td>${item.attendancePercent === null ? '—' : `${item.attendancePercent}%`}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}
      </div>
    </div>`;
    $('loadAdminDate').addEventListener('click', () => renderAdminDashboard($('adminDate').value));
    $('printStudentRegistration').addEventListener('click', () => printStudentRegistration(data));
    loadAdminParentTools();
    $('principalMessageForm').addEventListener('submit', async event => { event.preventDefault(); $('principalMessageError').textContent=''; try { const result=await api('/api/admin/parent-tools/message',{method:'PUT',body:JSON.stringify({message:$('principalMessageInput').value})}); showToast(result.message); } catch(error) { $('principalMessageError').textContent=error.message; } });
    $('refreshAbsenceReasons').addEventListener('click', loadAdminAbsenceReasons);
  }

  async function loadAdminParentTools() {
    try { const data=await api('/api/parent/message'); $('principalMessageInput').value=data.message || ''; } catch(_) {}
    await loadAdminAbsenceReasons();
  }
  async function loadAdminAbsenceReasons() {
    const target=$('absenceReasonList'); if(!target) return;
    try { const data=await api(`/api/admin/parent-tools/absence-reasons?date=${encodeURIComponent(state.adminDate || new Date().toISOString().slice(0,10))}`);
      target.innerHTML=data.reasons.length ? `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>ID</th><th>Class</th><th>Reason</th><th>Submitted</th><th>Action</th></tr></thead><tbody>${data.reasons.map(r=>`<tr><td>${esc(r.student_name)}</td><td>${esc(r.student_id)}</td><td>${esc(r.class_name)}</td><td>${esc(r.reason)}</td><td>${esc(fmtDateTime(r.submitted_at))}</td><td><button class="button button-secondary button-small" data-edit-reason="${r.id}" data-reason-text="${esc(r.reason).replaceAll('&quot;','&amp;quot;')}">EDIT ABSENT REASON</button></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-state">No absence reasons have been submitted today.</div>';
      target.querySelectorAll('[data-edit-reason]').forEach(button=>button.addEventListener('click',async()=>{const updated=window.prompt('Edit absence reason (any language, up to 500 characters):',button.dataset.reasonText);if(updated===null)return;try{const result=await api(`/api/admin/parent-tools/absence-reasons/${button.dataset.editReason}`,{method:'PUT',body:JSON.stringify({reason:updated})});showToast(result.message);await loadAdminAbsenceReasons();}catch(error){showToast(error.message,true);}}));
    } catch(error) { target.textContent=error.message; }
  }

  function printStudentRegistration(data) {
    const rows = data.sections.map(item => `<tr><td>${esc(item.className)}</td><td>${esc(item.section)}</td><td>${item.studentCount}</td><td>${item.registration?'REGISTERED':'PENDING'}</td><td>${item.registration?item.registration.present:'—'}</td><td>${item.registration?item.registration.absent:'—'}</td><td>${item.attendancePercent===null?'—':item.attendancePercent+'%'}</td></tr>`).join('');
    const printWindow = window.open('', '_blank', 'width=1100,height=800');
    if (!printWindow) { showToast('Please allow pop-ups to print the registration record.', true); return; }
    printWindow.document.write(`<!doctype html><html><head><title>Student Registration - ${esc(data.date)}</title><style>body{font-family:Arial,sans-serif;padding:28px;color:#173b30}h1{margin:0 0 5px}p{color:#66756e}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #cfdad4;padding:8px;text-align:left;font-size:12px}th{background:#f2f7f3} .summary{display:flex;gap:22px;margin-top:15px} .summary b{font-size:20px}</style></head><body><h1>Gamini Central College Nuwara Eliya</h1><h2>School-wide Student Registration Record</h2><p>Date: ${esc(fmtDate(data.date))}</p><div class="summary"><span>Registered classes <b>${data.registeredClasses}/${data.totalClasses}</b></span><span>Present <b>${data.stats.present}</b></span><span>Absent <b>${data.stats.absent}</b></span><span>Attendance <b>${data.stats.attendancePercent}%</b></span></div><table><thead><tr><th>Class</th><th>Section</th><th>Active Students</th><th>Registration</th><th>Present</th><th>Absent</th><th>Attendance</th></tr></thead><tbody>${rows}</tbody></table><p>Printed from the School Registration System.</p></body></html>`);
    printWindow.document.close(); printWindow.focus(); setTimeout(() => printWindow.print(), 250);
  }


  async function renderStaffRegistration(date = new Date().toISOString().slice(0,10)) {
    setPage('Staff registration','STAFF OPERATIONS');
    const data = await api(`/api/staff-registration?date=${encodeURIComponent(date)}`);
    state.adminDate = data.date;
    $('viewContainer').innerHTML = `<div class="view">
      <div class="welcome-row"><div><p class="eyebrow">${esc(state.user.role)} · ${fmtDate(data.date)}</p><h3>Academic & non-academic staff registration</h3><p class="muted">Register staff by name, ID and staff role. Records are kept for the current school year and cleared at year end.</p></div>
      <button class="button button-primary" id="openStaffRegistration">REGISTER STAFF</button></div>
      <div class="section-card"><div class="section-card-header"><div><h3>Daily staff registration</h3><p class="muted">Select a date to review the school-wide staff registration record.</p></div><div class="toolbar"><label class="date-filter-label">Registration date<input id="staffDate" type="date" value="${esc(data.date)}"></label><button class="button button-secondary" id="loadStaffDate">VIEW DATE</button><button class="button button-secondary" id="printStaffRegistration">PRINT STAFF RECORD</button></div></div>
      ${data.registrations.length ? `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Name</th><th>Staff role</th><th>Entrance</th><th>Departure</th><th>Registered by</th>${data.canDelete?'<th>Action</th>':''}</tr></thead><tbody>${data.registrations.map(r=>`<tr><td><strong>${esc(r.staff_id)}</strong></td><td>${esc(r.name)}</td><td>${esc(r.role)}</td><td>${esc(r.reported_time || '—')}</td><td>${esc(r.departure_time || '—')}</td><td>${esc(r.registered_by)}</td>${data.canDelete?`<td><button class="button button-danger button-small" data-staff-delete="${r.id}" data-staff-ref="${esc(r.staff_id)}">DELETE ID</button></td>`:''}</tr>`).join('')}</tbody></table></div>` : '<div class="empty-state">No staff registration records are available for this date.</div>'}
      </div>
    </div>`;
    $('openStaffRegistration').addEventListener('click', openStaffRegistrationModal);
    $('loadStaffDate').addEventListener('click', () => renderStaffRegistration($('staffDate').value));
    $('printStaffRegistration').addEventListener('click', () => printStaffRegistration(data));
    document.querySelectorAll('[data-staff-delete]').forEach(btn => btn.addEventListener('click', async () => {
      if (!window.confirm(`Delete the staff registration record for ${btn.dataset.staffRef}?`)) return;
      try { const result = await api(`/api/staff-registration/${btn.dataset.staffDelete}/delete`, {method:'POST'}); showToast(result.message); await renderStaffRegistration(data.date); }
      catch(error) { showToast(error.message, true); }
    }));
  }

  function openStaffRegistrationModal() {
    $('staffRegDate').value = state.adminDate || new Date().toISOString().slice(0,10);
    $('staffFormError').textContent = '';
    $('staffRegId').value=''; $('staffRegName').value=''; $('staffRegRole').value=''; $('staffRegDeparture').value=''; $('staffRegTime').value = new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Colombo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
    openModal('staffModal');
  }

  async function saveStaffRegistration(event) {
    event.preventDefault(); $('staffFormError').textContent='';
    try {
      const result = await api('/api/staff-registration',{method:'POST',body:JSON.stringify({
        staffId:$('staffRegId').value, name:$('staffRegName').value.trim(), role:$('staffRegRole').value, departureTime:$('staffRegDeparture').value,
        registrationDate:$('staffRegDate').value || new Date().toISOString().slice(0,10)
      })});
      closeModal('staffModal'); showToast(result.message); if (state.user && ['Principal','Vice Principal','Assistant Principal','administrator'].includes(state.user.role)) await renderStaffRegistration($('staffRegDate').value || new Date().toISOString().slice(0,10));
    } catch(error) { $('staffFormError').textContent=error.message; }
  }

  function openParentTool(tool) {
    if (tool === 'verify') { $('parentVerifyError').textContent=''; $('parentVerifyResult').textContent=''; openModal('parentVerifyModal'); }
    if (tool === 'reason') { $('parentReasonError').textContent=''; openModal('parentReasonModal'); }
    if (tool === 'birthdays') { openModal('parentBirthdaysModal'); loadTodayBirthdays(); }
    if (tool === 'message') { openModal('parentMessageModal'); loadPublicPrincipalMessage(); }
  }

  async function verifyParentStudent(event) {
    event.preventDefault(); $('parentVerifyError').textContent=''; $('parentVerifyResult').textContent='Checking attendance…';
    try { const data=await api('/api/parent/verify',{method:'POST',body:JSON.stringify({studentId:$('parentVerifyId').value.trim(),className:$('parentVerifyClass').value})});
      const statusLabel=data.status==='present'?'PRESENT':data.status==='absent'?'ABSENT':'NOT SUBMITTED';
      $('parentVerifyResult').innerHTML=`<div class="parent-status ${esc(data.status)}"><strong>${esc(data.studentName)}</strong><span>${esc(data.className)} · ${esc(fmtDate(data.date))}</span><b>${statusLabel}</b><p>${esc(data.message)}</p></div>`;
    } catch(error) { $('parentVerifyResult').textContent=''; $('parentVerifyError').textContent=error.message; }
  }

  async function submitParentAbsenceReason(event) {
    event.preventDefault(); $('parentReasonError').textContent='';
    try { const data=await api('/api/parent/absence-reason',{method:'POST',body:JSON.stringify({studentName:$('parentReasonName').value.trim(),studentId:$('parentReasonId').value.trim(),className:$('parentReasonClass').value,reason:$('parentReasonText').value.trim()})});
      closeModal('parentReasonModal'); $('parentReasonForm').reset(); showToast(data.message);
    } catch(error) { $('parentReasonError').textContent=error.message; }
  }

  async function loadTodayBirthdays() {
    const target=$('birthdayList'); if (!target) return; target.textContent='Loading today’s birthdays…';
    try { const data=await api('/api/parent/birthdays'); target.innerHTML=data.students.length ? data.students.map(student=>`<div class="birthday-card"><span class="birthday-icon">🎂</span><div><strong>Happy Birthday, ${esc(student.full_name)}!</strong><p>Class ${esc(student.class_name)} · Wishing you a joyful year full of learning and success.</p></div></div>`).join('') : '<div class="empty-state">No student birthdays are recorded for today. Check back tomorrow!</div>'; }
    catch(error) { target.textContent=error.message; }
  }

  async function loadPublicPrincipalMessage() {
    const target=$('publicPrincipalMessage'); if (!target) return;
    try { const data=await api('/api/parent/message'); target.innerHTML=data.message ? `<p>${esc(data.message).replaceAll('\n','<br>')}</p><small>${data.updatedAt ? `Updated ${esc(fmtDateTime(data.updatedAt))}` : ''}</small>` : '<p>No message has been published by the principal yet.</p>'; }
    catch(error) { target.textContent=error.message; }
  }

  function printStaffRegistration(data) {
    const rows=data.registrations.map(r=>`<tr><td>${esc(r.staff_id)}</td><td>${esc(r.name)}</td><td>${esc(r.role)}</td><td>${esc(r.reported_time || '—')}</td><td>${esc(r.departure_time || '—')}</td></tr>`).join('');
    const w=window.open('','_blank','width=1000,height=700'); if(!w){showToast('Please allow pop-ups to print the staff record.',true);return;}
    w.document.write(`<!doctype html><html><head><title>Staff Registration - ${esc(data.date)}</title><style>body{font-family:Arial;padding:28px;color:#173b30}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #cfdad4;padding:8px;font-size:12px;text-align:left}th{background:#f2f7f3}</style></head><body><h1>Gamini Central College Nuwara Eliya</h1><h2>Staff Registration Record</h2><p>Date: ${esc(fmtDate(data.date))}</p><table><thead><tr><th>ID</th><th>Name</th><th>Staff Role</th><th>Entrance</th><th>Departure</th></tr></thead><tbody>${rows}</tbody></table></body></html>`);
    w.document.close(); w.focus(); setTimeout(()=>w.print(),250);
  }

  async function renderAudit() {
    setPage('Audit log','ACCOUNTABILITY');
    const data = await api('/api/audit');
    $('viewContainer').innerHTML = `<div class="view"><div class="welcome-row"><div><p class="eyebrow">AUTHORIZED ADMINISTRATION</p><h3>Audit log</h3><p class="muted">Important actions are recorded with timestamp, user, and relevant record.</p></div>${data.canDelete?'<button class="button button-danger" id="deleteAuditData">DELETE AUDIT DATA</button>':''}</div><div class="section-card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Timestamp</th><th>User ID</th><th>Action</th><th>Record / Class</th><th>Details</th></tr></thead><tbody>${data.audit.map(row=>`<tr><td>${fmtDateTime(row.timestamp)}</td><td>${esc(row.user_id||'SYSTEM')}</td><td class="audit-action">${esc(row.action)}</td><td>${esc(row.record_ref||'—')} ${row.class_name?`· ${esc(row.class_name)}`:''}</td><td>${esc(row.details||'—')}</td></tr>`).join('')}</tbody></table></div></div></div>`;
    $('deleteAuditData')?.addEventListener('click', async () => {
      if (!window.confirm('Delete all audit log data? This cannot be undone.')) return;
      try { const result = await api('/api/audit/delete', {method:'POST'}); showToast(result.message); await renderAudit(); }
      catch(error) { showToast(error.message, true); }
    });
  }

  async function initDbPage() {
    const number=Number(pathName.split('/').pop());
    const titles={1:['DATABASE 1','STUDENT INFORMATION','Browse active student records organized by class.'],2:['DATABASE 2','DAILY REGISTRATION','Review daily attendance submissions grouped by date and class.'],3:['DATABASE 3','STAFF ACCESS INFORMATION','Review configured staff IDs, roles, assignments, and status.'],4:['DATABASE 4','MASTER CREDENTIALS DATABASE','The Administrator can unlock with the admin ID and application password. The Principal must also provide the DB/4 password.'],5:['DATABASE 5','ABSENCE REASONS','One reason per student per day. Reasons are cleared at midnight local school time.'],6:['DATABASE 6','PRINCIPAL MESSAGES','Review and manually remove principal messages. Messages expire at Sunday 00:00.']};
    const meta=titles[number]||titles[1]; $('dbTitle').textContent=meta[0]; $('dbDescription').textContent=number===4?'Administrator: enter your staff ID and application password. The Principal must also enter the DB/4 password.':meta[2]; $('dbContentKicker').textContent=meta[0]; $('dbContentTitle').textContent=meta[1];
    if(number===5||number===6){
      $('dbPasswordLabel').classList.add('hidden');
      $('dbGate').classList.add('hidden');
      const allowedRoles=['administrator','Principal','Vice Principal','Assistant Principal'];
      const showContent=async()=>{ $('dbGate').classList.add('hidden'); $('dbContent').classList.remove('hidden'); $('dbExportButton').style.display='none'; $('dbLogoutButton').onclick=()=>window.location.href='/'; await loadDbContent(number); };
      try {
        const session=await api('/api/session');
        if(session.user && allowedRoles.includes(session.user.role)){ await showContent(); }
        else {
          $('dbGate').classList.remove('hidden');
          $('dbLoginForm').addEventListener('submit',async(event)=>{
            event.preventDefault(); $('dbLoginError').textContent='';
            try {
              const result=await api('/api/login',{method:'POST',body:JSON.stringify({staffId:$('dbStaffId').value.trim(),password:$('dbStaffPassword').value,mode:'admin'})});
              if(!result.user || !allowedRoles.includes(result.user.role)) throw new Error('Only the Administrator or Principal can access this database.');
              await showContent();
            } catch(error) { $('dbLoginError').textContent=error.message; }
          });
        }
      } catch(error) { $('dbGate').classList.remove('hidden'); $('dbLoginError').textContent=error.message; }
      return;
    }
    $('dbLoginForm').addEventListener('submit',async(event)=>{event.preventDefault();$('dbLoginError').textContent='';try{await api(`/api/db/${number}/unlock`,{method:'POST',body:JSON.stringify({staffId:$('dbStaffId').value.trim(),password:$('dbStaffPassword').value,databasePassword:$('dbPassword').value})});$('dbGate').classList.add('hidden');$('dbContent').classList.remove('hidden');$('dbExportButton').style.display=number===1||number===2?'inline-block':'none';$('dbExportButton').onclick=()=>{window.location.href=number===1?'/api/export/students.csv':'/api/export/registrations.csv'};$('dbLogoutButton').onclick=()=>window.location.reload();await loadDbContent(number);}catch(error){$('dbLoginError').textContent=error.message;}});
  }
  async function loadDbContent(number) { try { if(number===1){const data=await api('/api/db/1/students'); renderDb1(data.students);} if(number===2){const data=await api('/api/db/2/registrations'); renderDb2(data.registrations);} if(number===3){const data=await api('/api/db/3/users'); renderDb3(data.users);} if(number===4){const [data,passwordData]=await Promise.all([api('/api/db/4/credentials'),api('/api/db/4/database-passwords')]); renderDb4(data.credentials,passwordData.passwords);} if(number===5){const data=await api('/api/db/5/absence-reasons');renderDb5(data.reasons);} if(number===6){const data=await api('/api/db/6/messages');renderDb6(data.messages);} }catch(error){showToast(error.message,true); if(number===5||number===6){$('dbContent').classList.add('hidden');$('dbGate').classList.remove('hidden');$('dbLoginForm').classList.add('hidden');$('dbLoginError').textContent=error.message;}} }
  function renderDb5(reasons){$('dbContentBody').innerHTML=`<div class="db-table-card"><p class="muted">Each student can have one reason per date. Reasons support Unicode text in any language and are removed after the date ends at 00:00 Asia/Colombo.</p>${reasons.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Student</th><th>ID</th><th>Class</th><th>Reason</th><th>Submitted</th><th>Action</th></tr></thead><tbody>${reasons.map(r=>`<tr><td>${esc(r.reason_date)}</td><td>${esc(r.student_name)}</td><td>${esc(r.student_id)}</td><td>${esc(r.class_name)}</td><td>${esc(r.reason)}</td><td>${esc(fmtDateTime(r.submitted_at))}</td><td><button class="button button-secondary button-small" data-db-edit-reason="${r.id}" data-reason-text="${esc(r.reason).replaceAll('&quot;','&amp;quot;')}">EDIT</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No absence reasons for today.</div>'}</div>`;document.querySelectorAll('[data-db-edit-reason]').forEach(b=>b.addEventListener('click',async()=>{const reason=prompt('Edit reason (any language):',b.dataset.reasonText);if(reason===null)return;try{const result=await api(`/api/admin/parent-tools/absence-reasons/${b.dataset.dbEditReason}`,{method:'PUT',body:JSON.stringify({reason})});showToast(result.message);await loadDbContent(5);}catch(e){showToast(e.message,true);}}));}
  function renderDb6(messages){$('dbContentBody').innerHTML=`<div class="db-table-card"><p class="muted">Only administrator and principal-level accounts can access this database. Messages are automatically removed at the weekly boundary (Sunday 00:00, Asia/Colombo). You can also delete any message manually.</p>${messages.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Message</th><th>Created by</th><th>Created at</th><th>Action</th></tr></thead><tbody>${messages.map(m=>`<tr><td>${m.id}</td><td>${esc(m.message)}</td><td>${esc(m.created_by)}</td><td>${esc(fmtDateTime(m.created_at))}</td><td><button class="button button-danger button-small" data-delete-principal-message="${m.id}">REMOVE MESSAGE</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No principal messages.</div>'}</div>`;document.querySelectorAll('[data-delete-principal-message]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Permanently remove this principal message?'))return;try{const result=await api(`/api/db/6/messages/${b.dataset.deletePrincipalMessage}`,{method:'DELETE'});showToast(result.message);await loadDbContent(6);}catch(e){showToast(e.message,true);}}));}
  function renderDb4(credentials,passwords){ $('dbContentBody').innerHTML=`<div class="db-table-card"><div class="section-card-header"><div><h3>Database password management</h3><p class="muted">Protected access. Passwords are stored as salted hashes, so the current secret is never displayed. Only the Administrator can change database passwords; the Principal must know the DB/4 password to open this page.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Database</th><th>Current password</th><th>Last changed</th><th>Changed by</th><th>Change password</th></tr></thead><tbody>${passwords.map(p=>`<tr><td><strong>DB/${p.databaseNumber}</strong></td><td>${esc(p.password)}</td><td>${fmtDateTime(p.updatedAt)}</td><td>${esc(p.updatedBy)}</td><td><form class="db-password-change-form" data-db-number="${p.databaseNumber}"><input name="administratorPassword" type="password" required autocomplete="current-password" placeholder="Administrator password" aria-label="Administrator password for DB/${p.databaseNumber}"><input name="newPassword" type="password" required minlength="12" autocomplete="new-password" placeholder="New password (12+ chars)" aria-label="New password for DB/${p.databaseNumber}"><button class="button button-primary button-small" type="submit">UPDATE</button></form></td></tr>`).join('')}</tbody></table></div></div><div class="db-table-card"><div class="section-card-header"><div><h3>Application accounts</h3><p class="muted">Account directory only. Application passwords and password hashes are never displayed.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>User ID</th><th>Name</th><th>Role</th><th>Assigned class</th><th>Status</th><th>Last login</th></tr></thead><tbody>${credentials.map(u=>`<tr><td><strong>${esc(u.user_id)}</strong></td><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${esc(u.assigned_class||'School-wide')}</td><td><span class="status-badge ${u.active?'active':'pending'}">${u.active?'ACTIVE':'INACTIVE'}</span></td><td>${fmtDateTime(u.last_login)}</td></tr>`).join('')}</tbody></table></div></div>`; document.querySelectorAll('.db-password-change-form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const number=form.dataset.dbNumber;const values=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type=submit]');submit.disabled=true;try{const result=await api(`/api/db/4/database-passwords/${number}`,{method:'PUT',body:JSON.stringify(values)});showToast(result.message);form.reset();await loadDbContent(4);}catch(error){showToast(error.message,true);}finally{submit.disabled=false;}})); }
  function renderDb3(users){ const grouped={}; users.forEach(u=>(grouped[u.role] ||= []).push(u)); $('dbContentBody').innerHTML=`<div class="db-table-card"><div class="section-card-header"><div><h3>Staff and user administration</h3><p class="muted">Create or update staff IDs and assignments. Passwords are never displayed.</p></div></div><form id="staffAdminForm" class="form-grid two-col" style="border:1px solid var(--line);padding:16px;border-radius:10px;margin-bottom:24px"><label>User ID<input id="adminUserId" required placeholder="CT-6A-2026"></label><label>Name<input id="adminUserName" required></label><label>Role<select id="adminUserRole" required><option>Class Teacher</option><option>Assistant Class Teacher</option><option>Principal</option><option>Vice Principal</option><option>Assistant Principal</option><option value="administrator">Administrator</option></select></label><label>Assigned class<input id="adminAssignedClass" placeholder="e.g. 6A or 12T"></label><label>New password<input id="adminUserPassword" type="password" placeholder="Required for new users"></label><label>Status<select id="adminUserActive"><option value="true">Active</option><option value="false">Inactive</option></select></label><div class="span-2"><div id="staffAdminError" class="form-error"></div><button class="button button-primary" type="submit">SAVE STAFF USER</button></div></form>${Object.entries(grouped).map(([role,items])=>`<div class="db-group"><h3>${esc(role)}</h3><div class="data-table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Name</th><th>Role</th><th>Assigned class</th><th>Status</th><th>Last login</th><th>Action</th></tr></thead><tbody>${items.map(u=>`<tr><td><strong>${esc(u.user_id)}</strong></td><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${esc(u.assigned_class||'School-wide')}</td><td><span class="status-badge ${u.active?'active':'pending'}">${u.active?'ACTIVE':'INACTIVE'}</span></td><td>${fmtDateTime(u.last_login)}</td><td><button type="button" class="button button-danger button-small" data-user-delete="${esc(u.user_id)}">DELETE</button></td></tr>`).join('')}</tbody></table></div></div>`).join('')}</div>`; const roleField = $('adminUserRole'); const classField = $('adminAssignedClass'); const idField = $('adminUserId'); const syncSuggestedTeacherId = () => { const role = roleField.value; const className = classField.value.trim(); if (role === 'Class Teacher' || role === 'Assistant Class Teacher') { const suggestion = className ? buildTeacherIdSuggestion(role, className) : null; if (suggestion) { idField.placeholder = suggestion; if (!idField.value.trim()) idField.value = suggestion; } } else { idField.placeholder = 'e.g. PRI0102'; if (!idField.value.trim()) idField.value = ''; } }; roleField.addEventListener('change', syncSuggestedTeacherId); classField.addEventListener('input', syncSuggestedTeacherId); syncSuggestedTeacherId(); $('staffAdminForm').addEventListener('submit',async(event)=>{event.preventDefault();$('staffAdminError').textContent='';try{const result=await api('/api/db/3/users',{method:'POST',body:JSON.stringify({userId:$('adminUserId').value.trim(),name:$('adminUserName').value.trim(),role:$('adminUserRole').value,assignedClass:$('adminAssignedClass').value.trim(),password:$('adminUserPassword').value,active:$('adminUserActive').value==='true'})});showToast(result.message);await loadDbContent(3);}catch(error){$('staffAdminError').textContent=error.message;}}); document.querySelectorAll('[data-user-delete]').forEach(button => { button.addEventListener('click', async () => { const userId = button.dataset.userDelete; const confirmed = window.confirm(`Delete ${userId}?\n\nThis action can only be performed by the Principal.`); if (!confirmed) return; try { const result = await api('/api/db/3/users/delete',{method:'POST',body:JSON.stringify({userId})}); showToast(result.message); await loadDbContent(3); } catch (error) { showToast(error.message,true); } }); }); }

  if(pathName.startsWith('/DB/')) { initDbPage(); } else { bootstrap(); }
})();
